import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import Footer from '../components/Footer';
import { useCheckout } from '../context/CheckoutContext';

const Checkout2 = () => {
    const navigate = useNavigate();
    const { paymentData, updatePayment, checkoutTotals } = useCheckout();
    const [cartItems, setCartItems] = useState([]);
    const [selectedMethod, setSelectedMethod] = useState(paymentData.method || 'card');

    useEffect(() => {
        const items = JSON.parse(localStorage.getItem('bindass_cart')) || [];
        setCartItems(items);
    }, []);

    const handleProceed = () => {
        updatePayment({ method: selectedMethod });
        navigate('/checkout/review');
    };

    const paymentMethods = [
        { id: 'card', name: 'Credit / Debit Card', icon: 'credit_card', desc: 'Secure payment via Razorpay' },
        { id: 'upi', name: 'UPI / QR Code', icon: 'qr_code_2', desc: 'Instant mobile payment' },
        { id: 'netbanking', name: 'Net Banking', icon: 'account_balance', desc: 'Over 50+ banks supported' }
    ];

    return (
        <div className="bg-background-light dark:bg-background-dark text-slate-900 dark:text-slate-100 font-display min-h-screen">
            <Navbar />
            <main className="max-w-7xl mx-auto px-6 py-12">
                {/* Stepper */}
                <div className="mb-12 max-w-3xl">
                    <div className="flex items-center justify-between relative">
                        <div className="absolute top-1/2 left-0 w-full h-0.5 bg-primary/10 -z-10 -translate-y-1/2"></div>
                        <div 
                            className="flex flex-col items-center gap-2 bg-background-light pr-4 cursor-pointer group"
                            onClick={() => navigate('/checkout')}
                        >
                            <div className="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold shadow-lg shadow-emerald-500/20 transition-transform group-hover:scale-110">
                                <i className="material-icons text-sm">check</i>
                            </div>
                            <span className="text-[10px] font-bold uppercase tracking-widest text-emerald-500">Shipping</span>
                        </div>
                        <div className="flex flex-col items-center gap-2 bg-background-light px-4">
                            <div className="w-10 h-10 rounded-full bg-primary text-white flex items-center justify-center font-bold shadow-lg shadow-primary/20">2</div>
                            <span className="text-[10px] font-bold uppercase tracking-widest text-primary">Payment</span>
                        </div>
                        <div className="flex flex-col items-center gap-2 bg-background-light pl-4 opacity-50">
                            <div className="w-10 h-10 rounded-full bg-white border-2 border-primary/20 text-zinc-400 flex items-center justify-center font-bold">3</div>
                            <span className="text-[10px] font-bold uppercase tracking-widest text-zinc-400">Review</span>
                        </div>
                    </div>
                </div>

                <div className="flex flex-col lg:flex-row gap-12">
                    {/* Left Column: Payment Methods */}
                    <div className="flex-1 space-y-8">
                        <div>
                            <h1 className="text-3xl font-bold dark:text-black mb-2">Select Payment Method</h1>
                            <p className="text-slate-500 text-sm">All transactions are encrypted and secure.</p>
                        </div>

                        <div className="space-y-4">
                            {paymentMethods.map((method) => (
                                <div 
                                    key={method.id}
                                    onClick={() => setSelectedMethod(method.id)}
                                    className={`p-6 rounded-xl border-2 transition-all cursor-pointer flex items-center justify-between group ${
                                        selectedMethod === method.id 
                                        ? 'border-primary bg-primary/5 shadow-md shadow-primary/5' 
                                        : 'border-slate-100 bg-white hover:border-slate-300'
                                    }`}
                                >
                                    <div className="flex items-center gap-6">
                                        <div className={`w-12 h-12 rounded-lg flex items-center justify-center transition-colors ${
                                            selectedMethod === method.id ? 'bg-primary text-white' : 'bg-slate-50 text-slate-400'
                                        }`}>
                                            <i className="material-icons text-xl">{method.icon}</i>
                                        </div>
                                        <div>
                                            <h4 className="font-bold text-sm uppercase tracking-tight">{method.name}</h4>
                                            <p className="text-[11px] text-slate-500 font-medium">{method.desc}</p>
                                        </div>
                                    </div>
                                    <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${
                                        selectedMethod === method.id 
                                        ? 'border-primary bg-primary' 
                                        : 'border-slate-200'
                                    }`}>
                                        {selectedMethod === method.id && <div className="w-2 h-2 bg-white rounded-full" />}
                                    </div>
                                </div>
                            ))}
                        </div>

                        <div className="pt-4">
                            <button 
                                onClick={handleProceed}
                                className="w-full bg-[#10221c] text-white font-bold py-5 rounded-lg uppercase tracking-widest text-xs hover:bg-black transition-all active:scale-[0.98] shadow-lg shadow-black/10"
                            >
                                Continue to Review
                            </button>
                        </div>
                    </div>

                    {/* Right Column: Order Summary */}
                    <aside className="w-full lg:w-[400px]">
                        <div className="sticky top-28 bg-white p-8 rounded-xl border border-slate-200 shadow-sm">
                            <h3 className="text-lg font-bold mb-6 flex items-center justify-between dark:text-black uppercase tracking-tighter">
                                Order Summary
                                <span className="text-primary text-xs px-2 py-1 bg-primary/5 rounded-full">{cartItems.length} Items</span>
                            </h3>

                            <div className="space-y-4 mb-8 max-h-[250px] overflow-y-auto custom-scrollbar pr-2">
                                {cartItems.map((item, index) => (
                                    <div key={index} className="flex gap-4 border-b border-slate-50 pb-4">
                                        <div className="w-16 h-20 bg-slate-50 rounded overflow-hidden flex-shrink-0">
                                            <img src={item.image} className="w-full h-full object-cover" alt={item.name} />
                                        </div>
                                        <div className="flex-1 py-1">
                                            <h4 className="text-[11px] font-bold uppercase dark:text-black truncate leading-tight">{item.name}</h4>
                                            <p className="text-[9px] text-slate-400 mt-0.5">SIZE: {item.size} • QTY: {item.quantity}</p>
                                            <div className="text-[11px] font-bold mt-2 dark:text-black">₹{item.price.toLocaleString()}</div>
                                        </div>
                                    </div>
                                ))}
                            </div>

                            <div className="space-y-3 border-t pt-6">
                                <div className="flex justify-between text-[13px] text-slate-500">
                                    <span>Subtotal</span>
                                    <span className="dark:text-black font-semibold">₹{checkoutTotals.subtotal.toLocaleString()}</span>
                                </div>
                                <div className="flex justify-between text-[13px] text-slate-500">
                                    <span>Shipping</span>
                                    <span className="text-emerald-600 font-bold uppercase text-[9px] tracking-widest">Complimentary</span>
                                </div>
                                <div className="flex justify-between text-[13px] text-slate-500">
                                    <span>Tax (8%)</span>
                                    <span className="dark:text-black font-semibold">₹{checkoutTotals.tax.toLocaleString()}</span>
                                </div>
                                <div className="flex justify-between text-lg font-bold pt-4 border-t mt-4 dark:text-black items-end">
                                    <span className="uppercase text-xs tracking-widest pb-1">Total Amount</span>
                                    <span className="text-2xl font-black text-[#10221c]">₹{checkoutTotals.totalAmount.toLocaleString()}</span>
                                </div>
                            </div>
                        </div>
                    </aside>
                </div>
            </main>
            <Footer />
        </div>
    );
};

